For $2\le k<m<n$ and $t\ge3$, the three reversals generate $\Sym_n$
if and only if
\begin{enumerate}
\item $\gcd(a,b)=1$;
\item $a,b$ have opposite parity if $n$ is even;
\item at least one of $n,m,k$ is congruent to $2$ or $3$ modulo $4$.
\end{enumerate}

Let $\mathcal P$ be any finite set of odd primes, and put
\[
 M=4\prod_{p\in\mathcal P}p,
 \qquad a_{\mathcal P}=\frac3{32}\prod_{p\in\mathcal P}(1-p^{-2}).
\]
For every integer $n\ge\max(\{4\}\cup\mathcal P)$ divisible by four,
\begin{equation}
 f(n)\le a_{\mathcal P}(n+2M)^2.
\end{equation}
Consequently,
\begin{equation}
 \limsup_{\substack{n\to\infty\\4\mid n}}\frac{f(n)}{n^2}
 \le\frac3{4\pi^2}.
\end{equation}

If $4\mid n$ and $\langle r_n,r_m,r_k\rangle=\Sym_n$ with
$2\le k<m<n$, then the ordered residue pair $(m,k)\pmod4$ belongs to
\begin{equation}
 \{(0,3),(1,2),(2,1),(2,3),(3,0),(3,2)\}.
\end{equation}
